"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26982"],{91364(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.pendencia_reenvio_exige_complementacao","status":422,"titulo":"A fase n\xe3o permite complementa\xe7\xe3o \u2014 consequ\xeancia PENDENCIA_REENVIO exige PermiteComplementacao"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.pendencia_reenvio_exige_complementacao","requisitos":["UNI-REQ-0070"],"oQueAconteceu":["A consequ\xeancia `PENDENCIA_REENVIO` s\xf3 faz sentido numa fase que admite complementa\xe7\xe3o de\\ndocumentos. A defini\xe7\xe3o trouxe um documento exigido, ou um grupo de alternativas (OU), com essa\\nconsequ\xeancia numa fase do cronograma que n\xe3o permite complementa\xe7\xe3o. A fase de um grupo \xe9 a\\nfase comum dos documentos que est\xe3o nele. A mensagem de detalhe nomeia a fase, mas n\xe3o diz se\\na consequ\xeancia \xe9 do documento ou do grupo.","A permiss\xe3o de complementar n\xe3o \xe9 escolhida no cronograma do processo: o pedido que define o\\ncronograma n\xe3o tem esse campo. A fase do cronograma herda a permiss\xe3o do cadastro da fase\\ncan\xf4nica e guarda uma c\xf3pia dela no momento em que o cronograma \xe9 definido; mudar o cadastro\\ndepois n\xe3o altera um cronograma j\xe1 definido. No cadastro, s\xf3 a fase can\xf4nica de homologa\xe7\xe3o das\\ninscri\xe7\xf5es aceita a permiss\xe3o\\n([`complementacao_apenas_fases_permitidas`](/erros/uniplus.configuracao.fase_canonica.complementacao_apenas_fases_permitidas)).","A aplica\xe7\xe3o de um modelo de formul\xe1rio tamb\xe9m define exig\xeancias, e a consequ\xeancia vem do modelo:\\num documento do modelo com `PENDENCIA_REENVIO` numa fase do processo que n\xe3o permite\\ncomplementa\xe7\xe3o recebe esta mesma recusa.","A confer\xeancia acontece depois das de v\xednculo com fase, formul\xe1rio e etapa, da repeti\xe7\xe3o por\\ngrupo e da idade m\xe1xima de emiss\xe3o: \xe9 a \xfaltima da defini\xe7\xe3o das exig\xeancias.","Esta \xe9 a confer\xeancia \\"de ida\\", ao escrever a exig\xeancia. A \\"de volta\\" \xe9 a que impede retirar a\\ncomplementa\xe7\xe3o de uma fase que j\xe1 tem exig\xeancia com essa consequ\xeancia\\n(`uniplus.selecao.fase_cronograma.pendencia_reenvio_exige_complementacao`)."],"comoResolver":["Primeiro, descubra quem declara `PENDENCIA_REENVIO` na fase nomeada: um documento exigido ou um\\ngrupo de alternativas (OU) com consequ\xeancia pr\xf3pria. Trocar s\xf3 a consequ\xeancia dos documentos n\xe3o\\ncorrige o caso em que a consequ\xeancia \xe9 do grupo, e vice-versa. Escolha um dos caminhos:","- permita a complementa\xe7\xe3o na fase, o que resolve os dois casos. A permiss\xe3o n\xe3o se configura no\\n  cronograma: se a fase \xe9 a de homologa\xe7\xe3o das inscri\xe7\xf5es, habilite a complementa\xe7\xe3o no\\n  cadastro da fase can\xf4nica e redefina o cronograma do processo, para que a fase do cronograma\\n  receba a permiss\xe3o atual do cadastro. Em qualquer outra fase o cadastro n\xe3o aceita a permiss\xe3o,\\n  e restam os dois caminhos seguintes;\\n- troque a consequ\xeancia de quem a declara (o documento ou o grupo) por outra das previstas;\\n- passe a exig\xeancia para uma fase que permita complementa\xe7\xe3o; no caso do grupo, isso vale para\\n  todos os documentos dele, que precisam ficar na mesma fase.","Na aplica\xe7\xe3o de um modelo de formul\xe1rio, a consequ\xeancia \xe9 a do modelo: resolva pelo primeiro\\ncaminho ou ajuste o modelo de formul\xe1rio no cadastro de Configura\xe7\xe3o.","Depois, envie a defini\xe7\xe3o de novo."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Aplica\xe7\xe3o de modelo de formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);